$baseUrlJs = json_encode(rtrim(BASE_URL, '/'), JSON_UNESCAPED_SLASHES);
$inlineJs = <<<'JS'
$(function(){
 var baseUrl=__BASE_URL__,table=null,currentYear=new Date().getFullYear(),matrixData=[],modalityMatrixData=[],reportYear=currentYear,complianceChart=null,monthlyChart=null,monthlySelection=null;
 function esc(v){return $('<div>').text(v==null?'':String(v)).html()}
 function dateText(v){if(!v)return '-';var s=String(v).slice(0,10),p=s.split('-');return p.length===3?p[2]+'/'+p[1]+'/'+p[0]:s}
 function matrixFiltered(){var q=$('#mxBuscar').val().trim().toLowerCase(),selected=$('#mxFamilia').val();return matrixData.map(function(f){if(selected&&f.codigo+'|'+f.nombre!==selected)return null;var fm=(f.codigo+' '+f.nombre).toLowerCase().indexOf(q)>=0,items=(f.equipos||[]).filter(function(e){return !q||fm||(e.codigo+' '+e.nombre).toLowerCase().indexOf(q)>=0});return items.length?{codigo:f.codigo,nombre:f.nombre,equipos:items}:null}).filter(Boolean)}
 function pct(e,p){return p>0?(e/p)*100:0}
 function pctText(e,p){return pct(e,p).toFixed(1)+'%'}
 function modalityFiltered(){var q=$('#mmBuscar').val().trim().toLowerCase(),selected=$('#mmFamilia').val();return modalityMatrixData.map(function(f){if(selected&&f.codigo+'|'+f.nombre!==selected)return null;var fm=(f.codigo+' '+f.nombre).toLowerCase().indexOf(q)>=0,items=(f.equipos||[]).filter(function(e){return !q||fm||(e.codigo+' '+e.nombre).toLowerCase().indexOf(q)>=0});return items.length?{codigo:f.codigo,nombre:f.nombre,equipos:items}:null}).filter(Boolean)}
